WITH RECURSIVE tokens(value, rest) AS (
  SELECT '', COALESCE(supertypes,'') || ',' FROM cards WHERE instr(',' || availability || ',', ',arena,') > 0 AND supertypes IS NOT NULL
  UNION ALL
  SELECT substr(rest, 1, instr(rest, ',') - 1), substr(rest, instr(rest, ',') + 1) FROM tokens WHERE rest <> ''
), subtype_tokens(value, rest) AS (
  SELECT '', COALESCE(subtypes,'') || ',' FROM cards WHERE instr(',' || availability || ',', ',arena,') > 0 AND subtypes IS NOT NULL
  UNION ALL
  SELECT substr(rest, 1, instr(rest, ',') - 1), substr(rest, instr(rest, ',') + 1) FROM subtype_tokens WHERE rest <> ''
)
SELECT DISTINCT trim(value) AS type FROM (SELECT value FROM tokens UNION ALL SELECT value FROM subtype_tokens) WHERE trim(value) <> '' ORDER BY type;

