SELECT s.name
FROM sets AS s
WHERE EXISTS (
    SELECT 1 FROM set_translations AS st
    WHERE st.setCode = s.code AND st.language = 'Korean'
)
AND NOT EXISTS (
    SELECT 1 FROM set_translations AS st
    WHERE st.setCode = s.code AND st.language LIKE '%Japanese%'
);
